// Applies the site's migrations (./migrations, generated by pnpm db:generate) to DATABASE_URL, then exits.
// Run it as its own step: pnpm db:migrate locally, docker compose run --rm site node migrate.mjs in production. The server never
// migrates on start, so a deploy and a schema change stay two separate, deliberate acts.
import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import pg from 'pg';

const url = process.env.DATABASE_URL;
if (!url) {
  console.error('DATABASE_URL is not set');
  process.exit(1);
}
const pool = new pg.Pool({ connectionString: url, max: 1 });
try {
  await migrate(drizzle({ client: pool }), {
    migrationsFolder: fileURLToPath(new URL('./migrations', import.meta.url)),
  });
  console.log(JSON.stringify({ level: 'info', message: 'migrations applied' }));
} finally {
  await pool.end();
}
